#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.14.0  -  One editor, reposts, pins, 40 languages
#   * One editing screen for posts and clips: Audio, Text, Stickers, Filters, Adjust,
#     Crop (photos), Trim and Mute (videos).
#   * Details: "Add music" and "Original quality" are gone.
#   * Report and Repost on every clip and in the post menu; a Reposts tab on Me.
#   * Long-press on your posts/clips: Analytics, Pin, Share, Copy link, Delete.
#   * "Music" is now "Audio". Epidemic 400 fixed (search always has a term).
#   * Change cover fixed, and a cover can come from the gallery.
#   * 40 languages (Settings > Language, with search).
# Run from the project root:   bash update_v1140_editor_reposts_languages.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="a11f2af2d4a0764ab7f25b9e81104584062d7e7f8358b86f769811b8e3f22356"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/screens/settings/settings_screen.dart ] || { echo "ERROR: v1.13.0 is not installed. Run update_v1130_settings_privacy_details.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.14.0 is in place."
echo ""
echo "IMPORTANT (once):"
echo "  1) Firestore rules: Firebase console -> Firestore Database -> Rules, paste the full"
echo "     contents of firebase/firestore.rules and press Publish. Reposts, pins and the"
echo "     repost counter need them."
echo "  2) Audio search (Epidemic): commit and push, then Vercel -> signer project ->"
echo "     Deployments -> Redeploy. The app already sends a search word, so the 400"
echo "     is fixed even before that."
exit 0
